export type Key = keyof typeof dict;

const LangContext = createContext<{ lang: Lang; setLang: (l: Lang) => void; t: (k: Key) => string; tx: (text: string) => string }>({
  lang: "ru",
  setLang: () => undefined,
  t: (k) => dict[k].ru,
  tx: (text) => phraseDict[text]?.ru ?? text,
});

export function LangProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>("ru");
  activeLanguage = lang;
  useEffect(() => {
    try {
      const saved = localStorage.getItem("bf_lang") as Lang | null;
      if (saved && dict.events[saved]) setLangState(saved);
    } catch {
      /* storage blocked */
    }
  }, []);
  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);
  const setLang = (l: Lang) => {
    setLangState(l);
    try {
      localStorage.setItem("bf_lang", l);
    } catch {
      /* storage blocked */
    }
  };
  return <LangContext.Provider value={{ lang, setLang, t: (k) => dict[k][lang], tx: (text) => lang === "en" ? text : phraseDict[text]?.[lang] ?? text }}>{children}</LangContext.Provider>;
}

export const useT = () => useContext(LangContext);
let activeLanguage: Lang = "ru";
export function translate(text: string): string {
  if (activeLanguage === "en") return text;
  const dictionaryKey = (Object.keys(dict) as Key[]).find((key) => dict[key].en === text);
  return dictionaryKey ? dict[dictionaryKey][activeLanguage] : phraseDict[text]?.[activeLanguage] ?? text;
}
export const localeOf = (lang: Lang) => (lang === "en" ? "en-GB" : lang === "kk" ? "kk-KZ" : "ru-RU");
